import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Warp-level sum reduction
__inline__ __device__ float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}
// Pass 1: each row is split across multiple cooperating blocks (chunks) to
// increase grid-level parallelism when N (number of rows) is small but the
// row length L is large. Blocks accumulate partial sums via atomics and the
// last block to finish for a given row computes mean/invstd for that row.
template <int BLOCK_THREADS>
__global__ void layernorm_reduce_kernel(
    const float* __restrict__ X,
    float* __restrict__ sum_buf,
    float* __restrict__ sumsq_buf,
    int* __restrict__ counter_buf,
    float* __restrict__ mean_buf,
    float* __restrict__ invstd_buf,
    int N, int64_t L, float eps, int blocks_per_row)
{
    const int row = blockIdx.x / blocks_per_row;
    const int chunk = blockIdx.x % blocks_per_row;
    const int tid = threadIdx.x;
    const float* x_row_ptr = X + (int64_t)row * L;
    const int64_t L4 = L / 4;
    const int64_t rem_start = L4 * 4;
    const float4* __restrict__ x_row4 = reinterpret_cast<const float4*>(x_row_ptr);
    const int64_t quads_per_block = (L4 + blocks_per_row - 1) / blocks_per_row;
    const int64_t qstart = (int64_t)chunk * quads_per_block;
    int64_t qend = qstart + quads_per_block;
    if (qend > L4) qend = L4;
    float local_sum = 0.0f;
    float local_sumsq = 0.0f;
    for (int64_t i = qstart + tid; i < qend; i += BLOCK_THREADS) {
        float4 v4 = x_row4[i];
        local_sum += v4.x + v4.y + v4.z + v4.w;
        local_sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    // Only the last chunk handles the scalar tail (elements after the last full float4)
    if (chunk == blocks_per_row - 1) {
        for (int64_t i = rem_start + tid; i < L; i += BLOCK_THREADS) {
            float v = x_row_ptr[i];
            local_sum += v;
            local_sumsq += v * v;
        }
    }
    local_sum = warpReduceSum(local_sum);
    local_sumsq = warpReduceSum(local_sumsq);
    constexpr int NUM_WARPS = BLOCK_THREADS / 32;
    __shared__ float s_sum[NUM_WARPS];
    __shared__ float s_sumsq[NUM_WARPS];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    if (lane_id == 0) {
        s_sum[warp_id] = local_sum;
        s_sumsq[warp_id] = local_sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        float sum_val = (lane_id < NUM_WARPS) ? s_sum[lane_id] : 0.0f;
        float sumsq_val = (lane_id < NUM_WARPS) ? s_sumsq[lane_id] : 0.0f;
        sum_val = warpReduceSum(sum_val);
        sumsq_val = warpReduceSum(sumsq_val);
        if (lane_id == 0) {
            atomicAdd(&sum_buf[row], sum_val);
            atomicAdd(&sumsq_buf[row], sumsq_val);
            __threadfence();
            int prev = atomicAdd(&counter_buf[row], 1);
            if (prev == blocks_per_row - 1) {
                float total_sum = sum_buf[row];
                float total_sumsq = sumsq_buf[row];
                float mean = total_sum / (float)L;
                float var = total_sumsq / (float)L - mean * mean;
                var = fmaxf(var, 0.0f);
                mean_buf[row] = mean;
                invstd_buf[row] = rsqrtf(var + eps);
            }
        }
    }
}
// Pass 2: normalize using a grid-stride loop so we can launch many more blocks
// than N, keeping the SMs saturated even though N is small.
__global__ void layernorm_normalize_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Gamma,
    const float* __restrict__ Beta,
    float* __restrict__ Y,
    const float* __restrict__ mean_buf,
    const float* __restrict__ invstd_buf,
    int64_t N, int64_t L)
{
    const int64_t total = N * L;
    const int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += stride) {
        int64_t row = idx / L;
        int64_t col = idx - row * L;
        float mean = mean_buf[row];
        float invstd = invstd_buf[row];
        float v = X[idx];
        float g = Gamma[col];
        float b = Beta[col];
        Y[idx] = (v - mean) * invstd * g + b;
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be CUDA");
    TORCH_CHECK(beta.is_cuda(), "beta must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
    TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");
    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();
    int64_t L = gamma_c.numel();
    TORCH_CHECK(x_c.numel() % L == 0, "x numel must be divisible by normalized_shape numel");
    int64_t N = x_c.numel() / L;
    auto y = torch::empty_like(x_c);
    auto opts_f = x_c.options();
    auto opts_i = x_c.options().dtype(at::kInt);
    auto sum_buf = torch::zeros({N}, opts_f);
    auto sumsq_buf = torch::zeros({N}, opts_f);
    auto counter_buf = torch::zeros({N}, opts_i);
    auto mean_buf = torch::empty({N}, opts_f);
    auto invstd_buf = torch::empty({N}, opts_f);
    constexpr int BLOCK_THREADS = 256;
    int64_t L4 = L / 4;
    int blocks_per_row = 128;
    if (L4 < (int64_t)blocks_per_row) {
        blocks_per_row = (int)std::max((int64_t)1, L4);
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    dim3 block1(BLOCK_THREADS);
    dim3 grid1((unsigned)(N * blocks_per_row));
    layernorm_reduce_kernel<BLOCK_THREADS><<<grid1, block1, 0, stream>>>(
        x_c.data_ptr<float>(),
        sum_buf.data_ptr<float>(),
        sumsq_buf.data_ptr<float>(),
        counter_buf.data_ptr<int>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        (int)N, L, (float)eps, blocks_per_row
    );
    auto err1 = cudaGetLastError();
    TORCH_CHECK(err1 == cudaSuccess, "layernorm_reduce_kernel launch failed: ", cudaGetErrorString(err1));
    constexpr int BLOCK_THREADS2 = 256;
    int64_t total_elems = N * L;
    int64_t desired_blocks = (total_elems + BLOCK_THREADS2 - 1) / BLOCK_THREADS2;
    if (desired_blocks > 65535) desired_blocks = 65535;
    if (desired_blocks < 1) desired_blocks = 1;
    dim3 block2(BLOCK_THREADS2);
    dim3 grid2((unsigned)desired_blocks);
    layernorm_normalize_kernel<<<grid2, block2, 0, stream>>>(
        x_c.data_ptr<float>(),
        gamma_c.data_ptr<float>(),
        beta_c.data_ptr<float>(),
        y.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        N, L
    );
    auto err2 = cudaGetLastError();
    TORCH_CHECK(err2 == cudaSuccess, "layernorm_normalize_kernel launch failed: ", cudaGetErrorString(err2));
    return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Layer Normalization using a custom CUTE/CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            self.eps,
        )

