    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

template <int BLOCK_THREADS>
__global__ void layernorm_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Gamma,
    const float* __restrict__ Beta,
    float* __restrict__ Y,
    int N, int64_t L, float eps)
{
    const int n = blockIdx.x;
    const int tid = threadIdx.x;
    const float* x_row_ptr = X + (int64_t)n * L;
    float* y_row_ptr = Y + (int64_t)n * L;
    // Vectorized (float4) view of the row when possible
    const int64_t L4 = L / 4;
    const int64_t rem_start = L4 * 4;
    const float4* __restrict__ x_row4 = reinterpret_cast<const float4*>(x_row_ptr);
    float4* __restrict__ y_row4 = reinterpret_cast<float4*>(y_row_ptr);
    const float4* __restrict__ g_row4 = reinterpret_cast<const float4*>(Gamma);
    const float4* __restrict__ b_row4 = reinterpret_cast<const float4*>(Beta);
    // First pass: compute sum and sum of squares (vectorized main loop + scalar tail)
    float local_sum = 0.0f;
    float local_sumsq = 0.0f;
    for (int64_t i = tid; i < L4; i += BLOCK_THREADS) {
        float4 v4 = x_row4[i];
        local_sum += v4.x + v4.y + v4.z + v4.w;
        local_sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    for (int64_t i = rem_start + tid; i < L; i += BLOCK_THREADS) {
        float v = x_row_ptr[i];
        local_sum += v;
        local_sumsq += v * v;
    }
    // Warp-level reduction
    local_sum = warpReduceSum(local_sum);
    local_sumsq = warpReduceSum(local_sumsq);
    // Shared memory for cross-warp reduction
    constexpr int NUM_WARPS = BLOCK_THREADS / 32;
    __shared__ float s_sum[NUM_WARPS];
    __shared__ float s_sumsq[NUM_WARPS];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    if (lane_id == 0) {
        s_sum[warp_id] = local_sum;
        s_sumsq[warp_id] = local_sumsq;
    }
    __syncthreads();
    __shared__ float s_mean;
    __shared__ float s_invstd;
    if (warp_id == 0) {
        float sum_val = (lane_id < NUM_WARPS) ? s_sum[lane_id] : 0.0f;
        float sumsq_val = (lane_id < NUM_WARPS) ? s_sumsq[lane_id] : 0.0f;
        sum_val = warpReduceSum(sum_val);
        sumsq_val = warpReduceSum(sumsq_val);
        if (lane_id == 0) {
            float mean = sum_val / (float)L;
            float var = sumsq_val / (float)L - mean * mean;
            var = fmaxf(var, 0.0f);
            s_mean = mean;
            s_invstd = rsqrtf(var + eps);
        }
    }
    __syncthreads();
    float mean = s_mean;
    float invstd = s_invstd;
    // Second pass: normalize and apply affine transform (vectorized main loop + scalar tail)
    for (int64_t i = tid; i < L4; i += BLOCK_THREADS) {
        float4 v4 = x_row4[i];
        float4 g4 = g_row4[i];
        float4 b4 = b_row4[i];
        float4 out4;
        out4.x = (v4.x - mean) * invstd * g4.x + b4.x;
        out4.y = (v4.y - mean) * invstd * g4.y + b4.y;
        out4.z = (v4.z - mean) * invstd * g4.z + b4.z;
        out4.w = (v4.w - mean) * invstd * g4.w + b4.w;
        y_row4[i] = out4;
    }
    for (int64_t i = rem_start + tid; i < L; i += BLOCK_THREADS) {
        float v = x_row_ptr[i];
        float g = Gamma[i];
        float b = Beta[i];
        float normalized = (v - mean) * invstd;
        y_row_ptr[i] = normalized * g + b;
    }
}

